import{_ as r,o as t,c as l,a2 as o}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"代码填泥 (Polyfill)","description":"","frontmatter":{},"headers":[],"relativePath":"polyfill.md","filePath":"polyfill.md","lastUpdated":1669882888000}'),a={name:"polyfill.md"};function i(p,e,s,n,f,c){return t(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="代码填泥-polyfill" tabindex="-1">代码填泥 (Polyfill)</h1><h2 id="定义" tabindex="-1">定义</h2><p>代码填泥, 又称 [ 填泥 / 腻子 / 泥子 ], 是一个完整的代码块, 用于为不支持原生 ECMAScript 新功能的环境提供功能支持.<br> 例如 Polyfill 可以让 AutoJs6 模拟 Array 原型上的 <a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/Array/at" target="_blank" rel="noreferrer">at</a> 等新增方法.</p><p>之所以被称为填泥, 是因为它主要用于 &quot;抹平&quot; 不同环境的功能支持差异.<br> 换句话说, 它是当前环境中某个标准 API 缺失后的手动实现.</p><blockquote><p>参阅: <a href="https://developer.mozilla.org/zh-CN/docs/Glossary/Polyfill" target="_blank" rel="noreferrer">MDN</a></p></blockquote><h2 id="autojs6-实现" tabindex="-1">AutoJs6 实现</h2><p>截至 2022 年 10 月, AutoJs6 实现了以下代码填泥:</p><ul><li><a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/Array/at" target="_blank" rel="noreferrer">Array.prototype.at</a></li><li><a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/Array/flat" target="_blank" rel="noreferrer">Array.prototype.flat</a></li><li><s><a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/Object/getOwnPropertyDescriptors" target="_blank" rel="noreferrer">Object.getOwnPropertyDescriptors</a></s> (Rhino 1.7.15-SNAPSHOT 已实现)</li></ul><h2 id="区别于-shim-代码垫片" tabindex="-1">区别于 Shim (代码垫片)</h2><p>Polyfill 与 Shim (代码垫片) 不同, Shim 针对的是环境, Polyfill 针对的是API.</p><p>Shim 作为 &quot;垫片&quot;, 主要用于为旧环境提供 API 或提供新功能.<br> 在使用 Shim 时, 通常不会在意旧环境是否已存在某 API, 它会直接改变或重新定义某些全局对象, 以实现在不同环境下功能的完整性和统一性.</p><p>Polyfill 是腻子, 用于抹平不同环境下的 API 差异, 它会判断旧环境是否已经存在 API, 不存在时才会添加新API.</p><blockquote><p>参阅: <a href="https://juejin.cn/post/6844904050882772999" target="_blank" rel="noreferrer">掘金</a> / <a href="https://stackoverflow.com/questions/6599815/what-is-the-difference-between-a-shim-and-a-polyfill" target="_blank" rel="noreferrer">StackOverflow</a></p></blockquote>',13)])])}const d=r(a,[["render",i]]);export{b as __pageData,d as default};
